import { searchComponents as searchComponentsData, getComponentsList, getCategoryData } from '../utils/jsonDataLoader.js';

/**
 * Search for React Bits components
 */
export async function searchComponents(args) {
  const { 
    query = '', 
    category = null, 
    techStack = 'js-css', 
    limit = 10 
  } = args;

  try {
    let results = [];
    
    // Use the new JSON data loader to search components
    results = searchComponentsData(query, category, techStack, limit);

    if (results.length === 0) {
      return {
        content: [
          {
            type: 'text',
            text: query 
              ? `No components found matching "${query}"${category ? ` in category "${category}"` : ''}`
              : 'No components available'
          }
        ]
      };
    }

    // Format results
    const formattedResults = results.map(component => ({
      name: component.displayName,
      category: component.category,
      description: generateDescription(component.displayName, component.category),
      availableVersions: component.availableStacks,
      tags: generateTags(component.displayName, component.category),
      installCommand: `jsrepo add react-bits/${component.name}`,
      techStack: component.techStack,
      hasCSS: component.metadata?.hasCSS || false,
      isTypeScript: component.metadata?.isTypeScript || false
    }));

    const resultText = formatSearchResults(formattedResults, query, category, techStack);

    return {
      content: [
        {
          type: 'text',
          text: resultText
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error searching components: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

