/**
 * Generate tags for a component
 */
function generateTags(name, category) {
  const tags = [category];
  
  // Add tags based on component name
  if (name.includes('card')) tags.push('card', 'ui');
  if (name.includes('animation')) tags.push('animation');
  if (name.includes('hover')) tags.push('hover', 'interaction');
  if (name.includes('scroll')) tags.push('scroll', 'infinite');
  if (name.includes('3d') || name.includes('model')) tags.push('3d', 'webgl');
  if (name.includes('background') || category === 'backgrounds') tags.push('background', 'effect');
  if (name.includes('text') || category === 'text-animations') tags.push('text', 'typography');
  if (name.includes('grid')) tags.push('grid', 'layout');
  if (name.includes('particle')) tags.push('particles', 'physics');
  if (name.includes('glass') || name.includes('blur')) tags.push('glass', 'blur', 'modern');
  
  return [...new Set(tags)]; // Remove duplicates
}

/**
 * Format search results for display
 */
function formatSearchResults(results, query, category, techStack) {
  let output = '';
  
  // Header
  if (query) {
    output += `🔍 **Search Results for "${query}"**\n`;
  } else if (category) {
    output += `📂 **Components in "${category}" category**\n`;
  } else {
    output += `📋 **All Available Components**\n`;
  }
  
  if (category) {
    output += `Category: ${category}\n`;
  }
  
  output += `Tech Stack: ${techStack}\n`;
  output += `Found ${results.length} component(s)\n\n`;

  // Results
  results.forEach((component, index) => {
    output += `**${index + 1}. ${component.name}**\n`;
    output += `   Category: ${component.category}\n`;
    output += `   Description: ${component.description}\n`;
    output += `   Tags: ${component.tags.join(', ')}\n`;
    output += `   Install: \`${component.installCommand}\`\n`;
    output += `   Available versions: ${component.availableVersions.join(', ')}\n\n`;
  });

  // Usage hints
  output += `---\n`;
  output += `💡 **Next Steps:**\n`;
  output += `• Use \`get-react-bits-component\` to get the full code for any component\n`;
  output += `• Use \`get-react-bits-demo\` to see usage examples\n`;
  output += `• Use \`get-react-bits-install-guide\` for detailed setup instructions\n`;

  return output;
}
